# -*- coding: utf-8 -*-
"""BC Science Grade 11-12 courses (built with cabc_sci). UNITS(grade)."""
from cabc_sci import BU, S, GM

C11, LS, P11, ES = "Chemistry 11", "Life Sciences 11", "Physics 11", "Earth Sciences 11"
AP, C12, P12, GE = "Anatomy and Physiology 12", "Chemistry 12", "Physics 12", "Geology 12"


def UNITS(grade):
    return {11: G11, 12: G12}[grade]()


def L(a, b):
    return "<p>%s</p><p>%s</p>" % (a, b)


def U(course, sort, slug, std, title, short, kb, ks, a, b, ex, mist, faq, sets, what=None, allow=()):
    meta = "Free %s worksheets (BC Curriculum): %s. 100 questions with answers." % (course, what or short)
    return BU(course, sort, slug, std, title, short, meta, kb, ks, L(a, b), ex, mist, faq, sets, allow=allow)


def AL(X, name, n, *kinds):
    import al_phys
    al_phys.R = X.R
    return (X.al(getattr(al_phys, name), *kinds), n)


